test('teacher timetable renders the reference layout and recurring class start times',()=>{const a=app({},'2026-10-08T12:00:00');a.set("lang='en';role='teacher';tab='overview';location.pathname='/account';selectTimetableDate('2026-10-08');render()");const html=a.nodes['#app'].innerHTML;for(const cls of ['teacher-timetable','tt-toolbar','tt-mini-calendar','tt-resource-tabs','tt-grid-scroll','tt-grid-heading','tt-time-axis'])assert.match(html,new RegExp(`class="${cls}`));assert.match(html,/id="tt-date"[^>]*value="2026-10-08"/);assert.match(html,/Thu, Oct 8/);assert.match(html,/09:00<\/div><div>09:15<\/div><div>09:30/);assert.equal((html.match(/data-class-roster=/g)||[]).length,6);assert.match(html,/top:calc\(4 \* var\(--tt-row-height\)\)" data-class-roster="a"/);assert.match(html,/No Room Assigned/);assert.doesNotMatch(html,/Days left in trial|Guided Setup|Help &amp; Support|Switch branch|teacher-today/);a.click({classRoster:'a'});assert.equal(a.read('location.pathname'),'/account/classes/a');assert.match(a.nodes['#app'].innerHTML,/David Leung/);});
test('timetable date and week/day controls handle month and year boundaries',()=>{const a=app();a.set("role='teacher';tab='overview';location.pathname='/account';selectTimetableDate('2027-01-01');render()");assert.deepEqual(a.read('timetableDays().map(timetableDateKey)'),['2026-12-28','2026-12-29','2026-12-30','2026-12-31','2027-01-01','2027-01-02','2027-01-03']);a.click({action:'tt-next'});assert.equal(a.read('timetableDate'),'2027-01-08');a.click({action:'tt-prev'});assert.equal(a.read('timetableDate'),'2027-01-01');a.change('','day',{id:'tt-view'});assert.deepEqual(a.read('timetableDays().map(timetableDateKey)'),['2027-01-01']);a.click({action:'tt-prev'});assert.equal(a.read('timetableDate'),'2026-12-31');a.click({action:'tt-month-next'});assert.equal(a.read('timetableDate'),'2026-12-31');assert.equal(a.read('timetableMonth.getMonth()'),0);a.click({ttDate:'2027-01-15'});assert.equal(a.read('timetableDate'),'2027-01-15');a.change('','2027-02-30',{id:'tt-date'});assert.equal(a.read('timetableDate'),'2027-01-15');a.change('','2028-02-29',{id:'tt-date'});assert.equal(a.read('timetableDate'),'2028-02-29');a.change('','invalid',{id:'tt-view'});assert.equal(a.read('timetableView'),'day');});
test('timetable search supports names, case-insensitive class codes and multi-day classes',()=>{const a=app();a.set("lang='en';role='teacher';tab='overview';location.pathname='/account';selectTimetableDate('2026-10-08');db.classes[0].weekdays=[1,3];db.classes[0].courseName='繪畫 Atelier';db.classes[0].classCode='PAINT-01';render()");assert.equal((a.nodes['#app'].innerHTML.match(/data-class-roster="a"/g)||[]).length,2);a.submit('timetable-search',{search:'paint-01'});assert.equal((a.nodes['#app'].innerHTML.match(/data-class-roster=/g)||[]).length,2);a.change('',true,{id:'tt-hide-empty',checked:true});assert.match(a.nodes['#app'].innerHTML,/--tt-days:2/);a.submit('timetable-search',{search:'繪畫'});assert.match(a.nodes['#app'].innerHTML,/data-class-roster="a"/);a.submit('timetable-search',{search:'16:00'});assert.match(a.nodes['#app'].innerHTML,/data-class-roster="d"/);assert.match(a.nodes['#app'].innerHTML,/--tt-days:1/);a.submit('timetable-search',{search:'no such lesson'});assert.match(a.nodes['#app'].innerHTML,/No lessons match your search/);assert.doesNotMatch(a.nodes['#app'].innerHTML,/data-class-roster=/);a.click({action:'new-class'});assert.match(a.nodes['#modal-root'].innerHTML,/id="class-editor"/);});
test('timetable resource controls use actual assignments and keep independent selections',()=>{const a=app();a.set("lang='en';role='teacher';tab='overview';location.pathname='/account';selectTimetableDate('2026-10-08');db.classes[0].room='Room A';db.classes[0].teacher='Eileen';render()");a.change('tt-resource','Room A',{checked:true});assert.deepEqual(a.read('timetableSelections.rooms'),['Room A']);assert.equal((a.nodes['#app'].innerHTML.match(/data-class-roster=/g)||[]).length,1);a.click({ttResourceTab:'teachers'});assert.match(a.nodes['#app'].innerHTML,/No Teacher Assigned/);assert.match(a.nodes['#app'].innerHTML,/Eileen/);a.change('tt-resource','unassigned',{checked:true});assert.doesNotMatch(a.nodes['#app'].innerHTML,/data-class-roster=/);a.change('tt-resource','unassigned',{checked:false});a.change('tt-resource','Eileen',{checked:true});assert.deepEqual(a.read('timetableSelections.teachers'),['Eileen']);a.submit('timetable-resource-search',{search:'eileen'});assert.doesNotMatch(a.nodes['#app'].innerHTML,/value="unassigned"/);a.click({ttResourceTab:'rooms'});assert.match(a.nodes['#app'].innerHTML,/value="Room A" checked/);a.change('',true,{id:'tt-all-resources',checked:true});assert.deepEqual(a.read('timetableSelections.rooms'),['Room A','unassigned']);a.change('',false,{id:'tt-all-resources',checked:false});assert.deepEqual(a.read('timetableSelections.rooms'),[]);a.click({action:'tt-filters'});assert.match(a.nodes['#app'].innerHTML,/tt-workspace filters-hidden/);a.click({action:'tt-filters'});assert.equal(a.read('timetableFiltersVisible'),true);a.click({action:'tt-month-toggle'});assert.doesNotMatch(a.nodes['#app'].innerHTML,/class="tt-mini-grid"/);});
test('timetable extends the time grid for early and late classes without inventing a duration',()=>{const a=app();a.set("role='teacher';selectTimetableDate('2026-10-08');db.classes[0].time='07:15';db.classes[1].time='23:45'");assert.deepEqual(a.read('timetableRange(timetableDays())'),{start:420,end:1440});a.set("tab='overview';location.pathname='/account';render()");assert.match(a.nodes['#app'].innerHTML,/>07:00<\/div>/);assert.match(a.nodes['#app'].innerHTML,/>23:45<\/div>/);assert.doesNotMatch(a.nodes['#app'].innerHTML,/07:15\s*[–-]\s*\d/);});
test('students retain their personal calendar and cannot change teacher timetable controls',()=>{const a=app();a.set("lang='en';role='student';tab='overview';location.pathname='/account';render()");const before=a.nodes['#app'].innerHTML,date=a.read('timetableDate');assert.doesNotMatch(before,/class="teacher-timetable"|No Room Assigned|data-tab="new-enrolments"/);a.click({action:'tt-next'});a.click({ttDate:'2027-02-01'});a.click({ttResourceTab:'teachers'});a.change('','day',{id:'tt-view'});a.submit('timetable-search',{search:'secret'});assert.equal(a.read('timetableDate'),date);assert.equal(a.read('timetableView'),'week');assert.equal(a.read('timetableResource'),'rooms');assert.equal(a.read('timetableSearch'),'');assert.equal(a.nodes['#app'].innerHTML,before);});
